import Foundation
import SwiftUI

/// Eén groep waarin badges gecategoriseerd zijn in het bronpakket (bv.
/// "Resolution", "Audio", "Streaming"). Puur informatief — Veyra groepeert
/// badges niet apart, dit wordt alleen gebruikt als terugvalkleur voor een
/// filter dat zelf geen kleur meegeeft.
struct SourceBadgeGroup: Codable, Hashable {
    let id: String
    let name: String
    let color: String?
}

/// Eén badge-regel ("filter") binnen een pakket: een reguliere expressie
/// (`pattern`, bv. `"(?i)\\b1080[pi]?\\b"`) die vergeleken wordt met de
/// bronnaam/provider/omschrijving van een bron. Bij een match verschijnt de
/// badge-afbeelding, of anders een gekleurd label met `name`.
///
/// Dit is het echte JSON-formaat van externe bronbadge-pakketten (bv.
/// Xperience/Strand): twee arrays op het hoogste niveau, `groups` en
/// `filters` — geen los "naam van het pakket"-veld, vandaar dat
/// `SourceBadgePack` zelf een naam kiest (zie `addPack`).
struct SourceBadge: Codable, Hashable, Identifiable {
    let id: String
    let name: String
    let pattern: String
    let imageURL: URL?
    let tagColor: String?
    let borderColor: String?
    let textColor: String?
    let groupId: String?
    let isEnabled: Bool

    private enum CodingKeys: String, CodingKey {
        case id, name, pattern, imageURL, tagColor, borderColor, textColor, groupId, isEnabled
    }

    init(
        id: String,
        name: String,
        pattern: String,
        imageURL: URL? = nil,
        tagColor: String? = nil,
        borderColor: String? = nil,
        textColor: String? = nil,
        groupId: String? = nil,
        isEnabled: Bool = true
    ) {
        self.id = id
        self.name = name
        self.pattern = pattern
        self.imageURL = imageURL
        self.tagColor = tagColor
        self.borderColor = borderColor
        self.textColor = textColor
        self.groupId = groupId
        self.isEnabled = isEnabled
    }

    /// Handmatige decode i.p.v. gesynthetiseerde `Codable`: één rare of
    /// onvolledige regel in een pakket van 100+ filters mag niet het hele
    /// pakket laten mislukken, dus elk veld valt terug op een veilige
    /// standaardwaarde i.p.v. de decode te laten stuklopen.
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        id = (try? container.decode(String.self, forKey: .id)) ?? UUID().uuidString
        name = (try? container.decode(String.self, forKey: .name)) ?? "Badge"
        pattern = (try? container.decode(String.self, forKey: .pattern)) ?? ""
        imageURL = (try? container.decodeIfPresent(URL.self, forKey: .imageURL)) ?? nil
        tagColor = (try? container.decodeIfPresent(String.self, forKey: .tagColor)) ?? nil
        borderColor = (try? container.decodeIfPresent(String.self, forKey: .borderColor)) ?? nil
        textColor = (try? container.decodeIfPresent(String.self, forKey: .textColor)) ?? nil
        groupId = (try? container.decodeIfPresent(String.self, forKey: .groupId)) ?? nil
        isEnabled = (try? container.decodeIfPresent(Bool.self, forKey: .isEnabled)) ?? true
    }

    /// Test of deze badge past bij een bron, op basis van `pattern` als
    /// reguliere expressie (inline `(?i)` voor hoofdletterongevoelig werkt
    /// gewoon mee, dat is standaard ICU-regexsyntax). Een lege of ongeldige
    /// regex matcht nooit, in plaats van te crashen.
    func matches(_ haystack: String) -> Bool {
        guard isEnabled, !pattern.isEmpty,
              let regex = try? NSRegularExpression(pattern: pattern) else {
            return false
        }
        let range = NSRange(haystack.startIndex..<haystack.endIndex, in: haystack)
        return regex.firstMatch(in: haystack, range: range) != nil
    }
}

/// Eén geladen, lokaal opgeslagen badge-pakket.
struct SourceBadgePack: Codable, Hashable, Identifiable {
    let id: UUID
    let name: String
    let sourceURLString: String
    let groups: [SourceBadgeGroup]
    let badges: [SourceBadge]
    var updatedAt: Date
}

/// Hoe badges in het bronkeuzescherm getoond worden.
enum SourceBadgeMode: Hashable {
    case off
    case builtIn
    case pack(UUID)
}

extension SourceBadgeMode: Codable {
    private enum Kind: String, Codable { case off, builtIn, pack }
    private enum CodingKeys: String, CodingKey { case kind, packID }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let kind = try container.decode(Kind.self, forKey: .kind)
        switch kind {
        case .off:
            self = .off
        case .builtIn:
            self = .builtIn
        case .pack:
            let id = try container.decode(UUID.self, forKey: .packID)
            self = .pack(id)
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .off:
            try container.encode(Kind.off, forKey: .kind)
        case .builtIn:
            try container.encode(Kind.builtIn, forKey: .kind)
        case .pack(let id):
            try container.encode(Kind.pack, forKey: .kind)
            try container.encode(id, forKey: .packID)
        }
    }
}

/// De ruwe vorm van een pakket zoals die van een JSON-URL binnenkomt: alleen
/// `groups` en `filters` op het hoogste niveau — geen paknaam, vandaar dat
/// `addPack` er zelf een geeft (gebaseerd op de URL).
private struct SourceBadgePackWire: Decodable {
    let name: String?
    let groups: [SourceBadgeGroup]?
    let filters: [SourceBadge]?
}

/// Beheert de geladen badge-pakketten en welke badges actief getoond worden
/// in het bronkeuzescherm ("Bronverschijning" in Instellingen). Zelfde
/// opslagpatroon als `SourceOrderDefaults`: platte `UserDefaults`, maar hier
/// als `ObservableObject` omdat de instellingenlijst en het bronscherm live
/// moeten meebewegen met een nieuw toegevoegd of verwijderd pakket.
@MainActor
final class SourceBadgeStore: ObservableObject {
    static let shared = SourceBadgeStore()

    @Published private(set) var packs: [SourceBadgePack]
    @Published private(set) var mode: SourceBadgeMode
    @Published var lastError: String?
    @Published private(set) var isLoading = false

    private let defaults: UserDefaults
    private let packsKey = "sourceBadges.packs"
    private let modeKey = "sourceBadges.mode"

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.packs = Self.loadPacks(from: defaults, key: "sourceBadges.packs")
        self.mode = Self.loadMode(from: defaults, key: "sourceBadges.mode")

        // `savePacks`/`saveMode` schrijven al gewoon naar `UserDefaults`, en
        // `VeyraHubSyncService` synct diezelfde twee sleutels (zie daar)
        // tussen apparaten via VeyraHub -- die schrijft de binnengekomen
        // waarde ook via `defaults.set`, dus dit ene observer volstaat om
        // zowel eigen als van-de-Hub-binnengekomen wijzigingen op te pikken
        // zonder herstart van de app.
        NotificationCenter.default.addObserver(
            self, selector: #selector(externalDefaultsChanged),
            name: UserDefaults.didChangeNotification, object: defaults)
    }

    @objc private func externalDefaultsChanged() {
        let newPacks = Self.loadPacks(from: defaults, key: packsKey)
        if newPacks != packs { packs = newPacks }

        let newMode = Self.loadMode(from: defaults, key: modeKey)
        if newMode != mode { mode = newMode }
    }

    // MARK: - Persistence

    private static func loadPacks(from defaults: UserDefaults, key: String) -> [SourceBadgePack] {
        guard let data = defaults.data(forKey: key),
              let packs = try? JSONDecoder().decode([SourceBadgePack].self, from: data) else {
            return []
        }
        return packs
    }

    private func savePacks() {
        guard let data = try? JSONEncoder().encode(packs) else { return }
        defaults.set(data, forKey: packsKey)
    }

    private static func loadMode(from defaults: UserDefaults, key: String) -> SourceBadgeMode {
        guard let data = defaults.data(forKey: key),
              let mode = try? JSONDecoder().decode(SourceBadgeMode.self, from: data) else {
            // Standaard aan (de ingebouwde, Veyra-gestileerde set) i.p.v. uit --
            // dit was voorheen iets dat je zelf via een JSON-pakket-URL moest
            // toevoegen, maar de ingebouwde badges zijn goed genoeg om
            // meteen te tonen, zonder eerst naar "Bronverschijning" te hoeven.
            return .builtIn
        }
        return mode
    }

    private func saveMode() {
        guard let data = try? JSONEncoder().encode(mode) else { return }
        defaults.set(data, forKey: modeKey)
    }

    func setMode(_ newMode: SourceBadgeMode) {
        mode = newMode
        saveMode()
    }

    // MARK: - Pakket toevoegen

    /// Haalt een pakket op van een JSON-URL (formaat: `{ "groups": [...],
    /// "filters": [...] }`) en maakt het meteen actief als het het eerste
    /// pakket is (of als er nu nog geen badges aan staan). Opnieuw
    /// toevoegen van dezelfde URL werkt het bestaande pakket bij in plaats
    /// van een dubbele regel toe te voegen.
    func addPack(fromURLString urlString: String) async {
        let trimmed = urlString.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let url = URL(string: trimmed), let scheme = url.scheme, scheme.hasPrefix("http") else {
            lastError = "Dit is geen geldige URL."
            return
        }

        isLoading = true
        lastError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: url)
            guard let http = response as? HTTPURLResponse, (200...299).contains(http.statusCode) else {
                lastError = "Kon het pakket niet ophalen van die URL."
                return
            }

            let wire = try JSONDecoder().decode(SourceBadgePackWire.self, from: data)
            let filters = wire.filters ?? []
            guard !filters.isEmpty else {
                lastError = "Dit pakket bevat geen badges."
                return
            }

            let id = packs.first(where: { $0.sourceURLString == trimmed })?.id ?? UUID()
            let pack = SourceBadgePack(
                id: id,
                name: wire.name ?? Self.derivedName(from: url),
                sourceURLString: trimmed,
                groups: wire.groups ?? [],
                badges: filters,
                updatedAt: Date()
            )

            if let index = packs.firstIndex(where: { $0.id == id }) {
                packs[index] = pack
            } else {
                packs.append(pack)
            }
            savePacks()

            if mode == .off || packs.count == 1 {
                setMode(.pack(id))
            }
        } catch is DecodingError {
            lastError = "Kon het pakket niet lezen: ongeldige JSON."
        } catch {
            lastError = "Kon het pakket niet ophalen: \(error.localizedDescription)"
        }
    }

    /// Zonder eigen naam in de JSON valt terug op de bestandsnaam (zonder
    /// extensie) of anders de hostnaam uit de URL.
    private static func derivedName(from url: URL) -> String {
        let stem = url.deletingPathExtension().lastPathComponent
        if !stem.isEmpty, stem != "/" { return stem }
        return url.host ?? "Badgepakket"
    }

    func removePack(_ pack: SourceBadgePack) {
        packs.removeAll { $0.id == pack.id }
        savePacks()
        if case .pack(let activeID) = mode, activeID == pack.id {
            setMode(packs.first.map { .pack($0.id) } ?? .off)
        }
    }

    // MARK: - Ingebouwde badges

    /// Volledige badgeset, overgenomen uit het externe Xperience-badgepakket
    /// (https://xperience-app.com/badges/5702a9ef-e88a-4f01-b158-8f02d3ff17e6.json)
    /// zodat alle 128 badges standaard beschikbaar zijn zonder pakket-URL --
    /// resolutie, releasetype, HDR/DV/IMAX, encoders, audio, kanalen,
    /// streamingdiensten, special tags, kwaliteitstiers en taal/ondertitels.
    /// Elke categorie krijgt één kleur uit Veyra's eigen cyaan->rood-verloop
    /// (glazige, halfdoorschijnende vulling + volle rand in dezelfde tint,
    /// witte tekst) i.p.v. de felle standaardkleurtjes van het pakket zelf --
    /// zo blijft het herkenbaar Veyra, ook al is de dekking 1-op-1 met de bron.
    /// Een handvol patronen in het origineel leunt op onzichtbare
    /// merkertekens die alleen Xperience zelf invoegt (bv. 480p/360p/240p,
    /// DVDRip/HDTV/SCR/TC/TS/CAM, XviD/DivX, de vier ondertitel-badges) --
    /// die zijn vervangen door een gewone tekstherkenning zodat ze ook in
    /// Veyra echt kunnen matchen.
    static let builtIn: [SourceBadge] = [
        // Resolution
        SourceBadge(id: "builtin-r-4k", name: "4K", pattern: "(?i)^(?=.*(?:2160[pi]?|4k|uhd))(?!.*(?:1080[pi]?|720[pi]?))",
                    tagColor: "#33A8F0FF", borderColor: "#FFA8F0FF", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-qhd3fo", name: "480p", pattern: "(?i)\\b480[pi]?\\b",
                    tagColor: "#33A8F0FF", borderColor: "#FFA8F0FF", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-fiwf3j", name: "360p", pattern: "(?i)\\b360[pi]?\\b",
                    tagColor: "#33A8F0FF", borderColor: "#FFA8F0FF", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-0d1dqe", name: "240p", pattern: "(?i)\\b240[pi]?\\b",
                    tagColor: "#33A8F0FF", borderColor: "#FFA8F0FF", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-r9yyxc", name: "UHD", pattern: "(?i)\\buhd\\b",
                    tagColor: "#33A8F0FF", borderColor: "#FFA8F0FF", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-h44xha", name: "576p", pattern: "(?i)\\b576[pi]?\\b",
                    tagColor: "#33A8F0FF", borderColor: "#FFA8F0FF", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-r-1080", name: "FHD", pattern: "(?i)\\b1080[pi]?\\b|\\bfhd\\b|\\bfull[ ._-]?hd\\b",
                    tagColor: "#33A8F0FF", borderColor: "#FFA8F0FF", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-r-720", name: "HD", pattern: "(?i)\\b720[pi]?\\b",
                    tagColor: "#33A8F0FF", borderColor: "#FFA8F0FF", textColor: "#FFFFFFFF"),

        // Release
        SourceBadge(id: "builtin-q-r", name: "Remux", pattern: "(?i)^(?=(?:[\\s\\S]*)(?:\\b|(?<=hd))remux\\b)(?![\\s\\S]*(?:5★|4★|3★|2★|1★))",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-q-b", name: "BluRay", pattern: "(?i)^(?=(?:[\\s\\S]*)\\b(?:bluray|blu-ray)\\b)(?![\\s\\S]*remux)(?![\\s\\S]*(?:5★|4★|3★|2★|1★))",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-q-w", name: "WebDL", pattern: "(?i)^(?=(?:[\\s\\S]*)\\b(?:web[-_. ]?dl|webdl)\\b(?!.*rip))(?![\\s\\S]*(?:5★|4★|3★|2★|1★))",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-q-wr", name: "WebRip", pattern: "(?i)^(?=(?:[\\s\\S]*)\\bweb[-_. ]?rip\\b)(?![\\s\\S]*(?:5★|4★|3★|2★|1★))",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-vykqee", name: "DVDRip", pattern: "(?i)\\bdvdrip\\b",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-pi1esr", name: "HDTV", pattern: "(?i)\\bhdtv\\b",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-vhyuqo", name: "SCR", pattern: "(?i)\\b(?:scr|screener)\\b",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-27wqcy", name: "TC", pattern: "(?i)\\btc\\b",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-bi1brb", name: "TS", pattern: "(?i)\\bts\\b",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-b-30tpbg", name: "CAM", pattern: "(?i)\\bcam\\b",
                    tagColor: "#334FC3F7", borderColor: "#FF4FC3F7", textColor: "#FFFFFFFF"),

        // Visual
        SourceBadge(id: "builtin-v-hdr10p", name: "HDR10+", pattern: "(?i)(?:(?:^(?!.*\\b(?:dv|dovi|dolby[\\s._-]?vision)\\b)(?=.*hdr[\\s._-]?10[\\s._-]?(?:\\+|plus|p(?:lus)?|pius))|^(?=.{1,120}$)(?!.*[-_.](?:[A-Za-z0-9][A-Za-z0-9+&-]{1,19})(?:\\.(?:mkv|mp4|m2ts|ts|mov|m4v))?\\s*$)(?!.*\\b(?:dv|dovi|dolby[\\s._-]?vision)\\b)(?=.*hdr[\\s._-]?10[\\s._-]?(?:\\+|plus|p(?:lus)?|pius)))|⁤)",
                    tagColor: "#33FF2145", borderColor: "#FFFF2145", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-v-hdr10", name: "HDR10", pattern: "(?i)(?:^(?!.*\\b(?:dv|dovi|dolby[\\s._-]?vision)\\b)(?=.*hdr[\\s._-]?10)(?!.*hdr[\\s._-]?10[\\s._-]?(?:\\+|plus|p(?:lus)?|pius))|^(?=.{1,120}$)(?!.*[-_.](?:[A-Za-z0-9][A-Za-z0-9+&-]{1,19})(?:\\.(?:mkv|mp4|m2ts|ts|mov|m4v))?\\s*$)(?!.*\\b(?:dv|dovi|dolby[\\s._-]?vision)\\b)(?=.*hdr[\\s._-]?10)(?!.*hdr[\\s._-]?10[\\s._-]?(?:\\+|plus|p(?:lus)?|pius)))",
                    tagColor: "#33FF2145", borderColor: "#FFFF2145", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-v-hdr", name: "HDR", pattern: "(?i)(?:(?:^(?!.*\\b(?:dv|dovi|dolby[\\s._-]?vision)\\b)(?=.*\\b(?:HDR|HLG|PQ)\\b)(?!.*hdr[\\s._-]?10)|^(?=.{1,120}$)(?!.*[-_.](?:[A-Za-z0-9][A-Za-z0-9+&-]{1,19})(?:\\.(?:mkv|mp4|m2ts|ts|mov|m4v))?\\s*$)(?!.*\\b(?:dv|dovi|dolby[\\s._-]?vision)\\b)(?=.*\\b(?:HDR|HLG|PQ)\\b)(?!.*hdr[\\s._-]?10))|⁡)",
                    tagColor: "#33FF2145", borderColor: "#FFFF2145", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-v-imax-e", name: "IMAX Enhanced", pattern: "(?i)(?:\\bimax[\\s._-]?enhanced\\b|^(?=.*\\b(?:dsnp|ds\\+|disney\\+|bcore|bc)\\b)(?=.*\\bweb[\\s._-]?(?:dl|rip)\\b)(?=.*\\b(?<!non[\\s._-])imax\\b))",
                    tagColor: "#33FF2145", borderColor: "#FFFF2145", textColor: "#FFFFFFFF"),
        SourceBadge(id: "builtin-v-imax", name: "IMAX", pattern: "(?i)^(?=.*\\bIMAX\\b)(?!.*enhanced)",
                    tagColor: "#33FF2145", borderColor: "#FFFF2145", textColor: "#FFFFFFFF"),
