    // MARK: - Opzoeken

    /// Zoekt alle passende badges voor een bron, op basis van de actieve
    /// modus. Vergelijkt tegen elke tekst die de aanroeper meegeeft (bv.
    /// oorsprongsnaam, providernaam, bronnaam, omschrijving) — de
    /// opzoeklogica zelf is UI-onafhankelijk zodat zowel de iOS- als de
    /// tvOS-bronrij hem kunnen gebruiken. Een bron kan meerdere badges
    /// tegelijk verdienen (bv. "4K" én "Atmos"), dus dit geeft een lijst
    /// terug i.p.v. maximaal één badge.
    func badges(matching haystackParts: [String], limit: Int = 4) -> [SourceBadge] {
        let haystack = haystackParts.joined(separator: " ")
        guard !haystack.trimmingCharacters(in: .whitespaces).isEmpty else { return [] }

        let candidates: [SourceBadge]
        switch mode {
        case .off:
            return []
        case .builtIn:
            candidates = Self.builtIn
        case .pack(let id):
            guard let pack = packs.first(where: { $0.id == id }) else { return [] }
            candidates = pack.badges
        }

        var result: [SourceBadge] = []
        for badge in candidates where badge.matches(haystack) {
            result.append(badge)
            if result.count >= limit { break }
        }
        return result
    }
}

// MARK: - Kleur

extension Color {
    /// Kleine hex-parser voor badge-kleuren: ondersteunt zowel "#RRGGBB"
    /// als "#AARRGGBB" (alfa eerst, zoals gebruikt in externe badge-
    /// pakketten). Geeft `nil` bij een onherkenbare waarde, zodat de
    /// aanroeper netjes op een standaardkleur kan terugvallen.
    init?(sourceBadgeHex hex: String?) {
        guard var hexString = hex?.trimmingCharacters(in: .whitespacesAndNewlines) else { return nil }
        if hexString.hasPrefix("#") { hexString.removeFirst() }
        guard let value = UInt64(hexString, radix: 16) else { return nil }

        let r, g, b, a: Double
        switch hexString.count {
        case 8:
            a = Double((value >> 24) & 0xFF) / 255
            r = Double((value >> 16) & 0xFF) / 255
            g = Double((value >> 8) & 0xFF) / 255
            b = Double(value & 0xFF) / 255
        case 6:
            a = 1
            r = Double((value >> 16) & 0xFF) / 255
            g = Double((value >> 8) & 0xFF) / 255
            b = Double(value & 0xFF) / 255
        default:
            return nil
        }
        self = Color(red: r, green: g, blue: b, opacity: a)
    }
}
